<template>
  <section class="flex flex-col gap-4">
    <div class="flex flex-col gap-2">
      <template v-if="isLoadingProjectShortInfo">
        <Skeleton class="w-60 h-9 rounded-full" />
      </template>
      <template v-else-if="projectShortInfo">
        <PageTitle :subtitle="projectShortInfo.short_description" show-doc>
          <template #title>
            <span class="flex flex-row items-center gap-2">
              {{ projectShortInfo.name }}
              <template v-if="isEditPrefix"> - Edit</template>
              <Badge
                v-else
                class="text-base font-normal"
                :variant="getProjectStatus(projectShortInfo.status).variant"
                >{{ getProjectStatus(projectShortInfo.status).label }}</Badge
              >
            </span>
          </template>
          <FilterTabsNav :items="isEditPrefix ? processedEditProjectTabs : navigationItems" rounded />
        </PageTitle>
      </template>
    </div>
    <NuxtPage :project-short-info="projectShortInfo" :project-id="projectId" :tab-status="projectEditTabsStatus" />
  </section>
</template>
<script setup lang="ts">
import { getProjectStatus } from '~/constants/projects';
import { getProjectEditTabsStatus, getProjectShortInfo, getProjectTabsStatus } from '~/client';
import { TriangleAlert } from 'lucide-vue-next';
import type { ProjectMainNavigationItem, ProjectEditNavigationItem } from '~/types/projects';

const { userRole, isAdminOrManager } = useUserRole();

const projectId = computed(() => useRoute('projects-id').params?.id);
const isEditPrefix = computed(() => useRoute().name.startsWith('projects-id-edit'));

const { data: projectShortInfo, isLoading: isLoadingProjectShortInfo } = useQuery({
  key: () => ['project.short-info', projectId.value],
  query: () => getProjectShortInfo({ composable: '$fetch', path: { project_id: projectId.value } }),
  enabled: () => !!projectId.value,
});

const { data: projectEditTabsStatus, isLoading: isLoadingProjectEditTabsStatus } = useQuery({
  key: () => ['project-edit-tabs-status', projectId.value],
  query: () => getProjectEditTabsStatus({ composable: '$fetch', path: { project_id: projectId.value } }),
  enabled: () => useRoute().name.includes('projects-id-edit') && !!projectId.value,
});

const { data: projectTabsStatus, isLoading: isLoadingProjectTabsStatus } = useQuery({
  key: () => ['project-tabs-status', projectId.value],
  query: () => getProjectTabsStatus({ composable: '$fetch', path: { project_id: projectId.value } }),
  enabled: () => !!projectId.value && isAdminOrManager.value,
});

const navigationItems = computed<ProjectMainNavigationItem[]>(() =>
  (
    [
      {
        label: 'Overview',
        to: { name: 'projects-id', params: { id: projectId.value } },
        selected: useRoute().name === 'projects-id',
        types: ['signature', 'canvassing'],
        roles: ['admin', 'manager', 'canvasser', 'subcontractor_canvasser'],
      },
      {
        label: 'Kickoff Info',
        to: { name: 'projects-id-kickoff', params: { id: projectId.value } },
        selected: useRoute().name === 'projects-id-kickoff',
        types: ['signature', 'canvassing'],
        roles: ['admin', 'manager'],
      },
      {
        label: 'Signatures',
        to: { name: 'projects-id-signatures', params: { id: projectId.value } },
        selected: useRoute().name === 'projects-id-signatures',
        types: ['signature'],
        roles: ['admin', 'manager', 'canvasser', 'subcontractor_canvasser'],
      },
      {
        label: 'Assignments',
        to: { name: 'projects-id-assignments', params: { id: projectId.value } },
        selected: useRoute().name === 'projects-id-assignments',
        types: ['signature', 'canvassing'],
        roles: ['admin', 'manager'],
      },
      {
        label: 'Applications',
        to: { name: 'projects-id-applications', params: { id: projectId.value } },
        selected: useRoute().name === 'projects-id-applications',
        types: ['signature', 'canvassing'],
        roles: ['admin', 'manager'],
        count: projectTabsStatus.value?.applicants ?? undefined,
      },
      {
        label: 'Work Shifts',
        to: { name: 'projects-id-workshifts', params: { id: projectId.value } },
        selected: useRoute().name === 'projects-id-workshifts',
        types: ['canvassing'],
        roles: ['admin', 'manager', 'canvasser', 'subcontractor_canvasser'],
      },
      {
        label: 'Daily Review',
        to: { name: 'projects-id-daily-review', params: { id: projectId.value } },
        selected: useRoute().name === 'projects-id-daily-review',
        types: ['canvassing'],
        roles: ['admin', 'manager'],
      },
      {
        label: 'Conversations',
        to: { name: 'projects-id-conversations', params: { id: projectId.value } },
        selected: useRoute().name === 'projects-id-conversations',
        types: ['signature', 'canvassing'],
        roles: ['admin', 'manager'],
      },
      {
        label: 'Recruitment',
        to: { name: 'projects-id-recruitment', params: { id: projectId.value } },
        selected: useRoute().name === 'projects-id-recruitment',
        types: ['signature', 'canvassing'],
        roles: ['admin', 'manager'],
      },
      {
        label: 'Reports',
        to: { name: 'projects-id-reports', params: { id: projectId.value } },
        selected: useRoute().name === 'projects-id-reports',
        types: ['signature', 'canvassing'],
        roles: ['admin', 'manager'],
      },
    ] satisfies ProjectMainNavigationItem[]
  ).filter(
    (x) =>
      projectShortInfo.value?.type && x.types.includes(projectShortInfo.value.type) && x.roles.includes(userRole.value)
  )
);

const processedEditProjectTabs = computed<ProjectEditNavigationItem[]>(() => {
  const icon = { icon: TriangleAlert, class: 'stroke-warning-foreground size-5 mr-1' };

  return (
    [
      {
        label: 'General Info',
        to: { name: 'projects-id-edit-general-information', params: { id: projectId.value } },
        selected: useRoute().name === 'projects-id-edit-general-information',
        icon:
          projectEditTabsStatus.value && projectEditTabsStatus.value?.general_information !== 'success'
            ? icon
            : undefined,
        types: ['signature', 'canvassing'],
      },
      {
        label: 'Configuration',
        to: { name: 'projects-id-edit-project-configuration', params: { id: projectId.value } },
        selected: useRoute().name === 'projects-id-edit-project-configuration',
        icon:
          projectEditTabsStatus.value && projectEditTabsStatus.value?.project_configuration !== 'success'
            ? icon
            : undefined,
        types: ['signature', 'canvassing'],
      },
      {
        label: 'Voter Database',
        to: { name: 'projects-id-edit-voter-database', params: { id: projectId.value } },
        selected: useRoute().name === 'projects-id-edit-voter-database',
        icon:
          projectEditTabsStatus.value && projectEditTabsStatus.value?.voter_database !== 'success' ? icon : undefined,
        types: ['signature', 'canvassing'],
      },
      {
        label: 'KPI',
        to: { name: 'projects-id-edit-kpi-rules', params: { id: projectId.value } },
        selected: useRoute().name === 'projects-id-edit-kpi-rules',
        icon: projectEditTabsStatus.value && projectEditTabsStatus.value?.kpi_rules !== 'success' ? icon : undefined,
        types: ['canvassing'],
      },
      {
        label: 'Coaching',
        to: { name: 'projects-id-edit-coaching', params: { id: projectId.value } },
        selected: useRoute().name === 'projects-id-edit-coaching',
        icon:
          projectEditTabsStatus.value && projectEditTabsStatus.value?.coaching_config !== 'success' ? icon : undefined,
        types: ['canvassing'],
      },
      {
        label: 'Petition Template',
        to: { name: 'projects-id-edit-ballot-template', params: { id: projectId.value } },
        selected: useRoute().name === 'projects-id-edit-ballot-template',
        icon:
          projectEditTabsStatus.value && projectEditTabsStatus.value?.ballot_template !== 'success' ? icon : undefined,
        types: ['signature'],
      },
    ] satisfies ProjectEditNavigationItem[]
  ).filter((x) => projectShortInfo.value?.type && x.types.includes(projectShortInfo.value.type));
});
</script>
